"""Build benchmark-inspired Amazon modules using only RAZAB website product photos."""
from pathlib import Path
import json,html,re,hashlib
root=Path(__file__).resolve().parent
assets=root/'assets/amazon-store';assets.mkdir(exist_ok=True)
def esc(t):return html.escape(t,quote=True)
def photo(n):return '../products/'+n
photo_sources={Path(r['file']).name:r for filename in ['photo-sources.json','benchmark-sources.json'] for r in json.loads((root/'assets/products'/filename).read_text(encoding='utf-8')) if 'source' in r}
product_urls={'16-piece glass set':'https://razab.com/products/16-pc-glass-set','6500 ml large container':'https://razab.com/products/6500-ml-large-food-storage-container','Set of 2 glass loaf pans':'https://razab.com/products/set-of-2-glass-loaf-pans','1860 ml glass set of 2':'https://razab.com/products/1860-ml-glass'}
product_urls['4800 ml large container']='https://razab.com/products/4800-ml-glass-container-with-locking-lid'
css=(root/'store-artwork.css').read_text(encoding='utf-8')
modules=[];art=[]
def add(id,kind,body,classes='',mobile=True,width=3000,height=1500,product=None,copy=None,alt='',source=''):
 mh=500 if classes=='welcome' else 800 if classes=='closing' else 3000 if classes=='size-guide' else 1680 if 'text-tile' in classes else 2970 if classes in ['banner prep','banner collection','care-art'] else 2400
 sources=[]
 for name in re.findall(r'<img[^>]+src="\.\./products/([^"]+)"',body):
  record=photo_sources[name]
  sources.append(dict(file='assets/products/'+name,source=record['source'],sha256=hashlib.sha256((root/'assets/products'/name).read_bytes()).hexdigest()))
 m=dict(id=id,type=kind,desktop=id+'-desktop.jpg',mobile=id+'-mobile.jpg' if mobile else None,width=width,height=height,mobileWidth=1680 if mobile else None,mobileHeight=mh if mobile else None,product=product,referenceProductUrl=product_urls.get(product),amazonDestination=None,copy=copy or {},alt=alt,photographySource=source,sourceImages=sources);modules.append(m)
 art.append(f'<section class="artboard {classes}" id="{id}-desktop" data-export="{m["desktop"]}">{body}</section>')
 if mobile:art.append(f'<section class="artboard mobile {classes}" id="{id}-mobile" data-export="{m["mobile"]}">{body}</section>')
hero=f'<img class="scene" src="{photo("16-pc-glass-set-8.webp")}" alt=""><img class="header-logo" data-safe src="../razab-original-logo.png" alt="RAZAB"><p class="header-tagline" data-safe>Keep It Fresh, Keep It Razab.</p><span class="header-rule"></span>'
add('01-header','Store header',hero,'header-art',False,height=600,alt='RAZAB. Keep It Fresh, Keep It Razab. Glass food containers in a home kitchen.',source='Original RAZAB manufacturer photo and logo')
add('02-welcome','Full-width image','<h2 data-safe>THANK YOU FOR FOLLOWING US.</h2><p data-safe>Quality, organization, and everyday convenience. Thoughtfully made for your kitchen.</p>','welcome',height=320,alt='Thank you for following us. Quality, organization, and everyday convenience. Thoughtfully made for your kitchen.')
def banner(id,src,num,label,body,details,eyebrow,classes,product,source):
 specs='<i></i>'.join('<span>'+esc(s)+'</span>' for s in details)
 text=f'<img class="scene" src="{src}" alt=""><div class="copy"><p class="eyebrow" data-safe>{eyebrow}</p><h2 class="headline" data-safe>{num}</h2><p class="label" data-safe>{label}</p><p class="description" data-safe>{body}</p><div class="detail" data-safe>{specs}</div><span class="cta" data-safe>Shop Now <b aria-hidden="true">↗</b></span></div><span class="section-no">RAZAB / {id[:2]}</span>'
 clean=lambda s:html.unescape(s.replace('<br>',' ').replace('<span class="unit">','').replace('<span class="title">','').replace('</span>',''))
 copy=dict(prefix=eyebrow,heading=clean(num),label=clean(label),body=body,details=details,linkText='Shop Now')
 add(id,'Full-width product image',text,'banner '+classes,product=product,copy=copy,alt='. '.join([clean(num),clean(label),body,' · '.join(details)]),source=source)
banner('03-meal-prep',photo('16-pc-glass-set-0.webp'),'16 <span class="unit">PC</span><br><span class="title">MEAL PREP</span>','Food Storage<br>Containers','Prep your favorites. Make room for a fresh week.',['8 glass containers + 8 lids','30 oz each'],'THE MEAL PREP COLLECTION','prep','16-piece glass set','Original RAZAB website product photograph')
features=[('04-glass','High quality<br>borosilicate glass','Clarity you can see. Quality you can feel.','<path d="M8 14h34l-4 24H12L8 14Z M7 14v-5h36v5M17 20v10M23 20v10M29 20v10"/>'),('05-lids','BPA-free<br>plastic lids','Thoughtful materials for everyday use.','<path d="M38 10c-18-4-31 10-21 24 12 5 25-9 21-24ZM11 40l19-20M22 29v-9M22 29h9"/><text x="9" y="13" stroke="none" fill="currentColor" font-family="Inter" font-size="9" font-weight="600">BPA</text>'),('06-lock','Airtight<br>locking lids','Close with confidence. Keep it fresh.','<rect x="12" y="22" width="26" height="21" rx="3"/><path d="M17 22v-9a8 8 0 0 1 16 0v9M25 30v5"/>'),('07-care','Dishwasher<br>safe','Less cleaning. More time for the good things.','<rect x="7" y="5" width="36" height="40" rx="3"/><path d="M7 15h36M13 10h3M22 10h3M18 38a9 9 0 1 1 13 0M14 21v4M25 20v4M36 21v4"/>')]
for id,title,desc,svg in features:add(id,'Small feature image',f'<div class="icon-ring"></div><svg viewBox="0 0 50 50" aria-hidden="true">{svg}</svg><h2 data-safe>{title}</h2><p data-safe>{desc}</p>','feature',False,750,750,copy=dict(heading=title.replace('<br>',' '),body=desc),alt=title.replace('<br>',' ')+'. '+desc)
banner('08-extra-large',photo('6500-ml-large-food-storage-container-5.webp'),'6500 <span class="unit">ML</span><br><span class="title">EXTRA LARGE</span>','Room for the whole table.','From the family roast to generous gatherings. Keep the good food together.',['6500 ml / 220 oz','Locking lid with carry handle'],'MADE FOR GENEROUS MEALS','roast reverse','6500 ml large container','Original RAZAB website product photograph')
banner('09-loaf-pan',photo('set-of-2-glass-loaf-pans-12.webp'),'LOAF PAN','Bake. Cover. Keep it fresh.','Golden loaves, family recipes, and a little something to share. Beautifully at home in glass.',['Set of 2 glass loaf pans','1800 ml per pan'],'FROM OVEN TO EVERYDAY','bake','Set of 2 glass loaf pans','Original RAZAB website product photograph')
banner('10-everyday',photo('1860-ml-glass-10.webp'),'1860<span class="unit"> ml</span>','Good food. Ready to go.','A generous pair for colorful lunches, fresh salads, and the leftovers you look forward to.',['2 containers + 2 lids','63 oz each'],'THE EVERYDAY PAIR','everyday reverse','1860 ml glass set of 2','Original RAZAB manufacturer photograph')
add('11-16pc-photo','Large photo tile',f'<img class="scene" src="{photo("16-pc-glass-set-8.webp")}" alt=""><p class="caption" data-safe>A calmer kitchen starts with a little organization.</p>','square photo-tile',False,1500,1500,product='16-piece glass set',alt='RAZAB glass food storage containers on a kitchen counter.',source='Original RAZAB manufacturer photograph')
def text_tile(id,num,label,description,details,eyebrow,product):
 clean=num.replace('<span class="unit">','').replace('</span>','')
 body=f'<p class="eyebrow" data-safe>{eyebrow}</p><h2 class="headline" data-safe>{num}</h2><p class="label" data-safe>{label}</p><p class="description" data-safe>{description}</p><div class="detail" data-safe>{esc(details)}</div><span class="cta" data-safe>Shop Now <b aria-hidden="true">↗</b></span><span class="section-no">RAZAB / GLASS FOOD STORAGE</span>'
 add(id,'Large text image tile',body,'square text-tile',True,1500,1500,product=product,copy=dict(heading=clean,label=label,body=description,details=details,linkText='Shop Now'),alt=clean+'. '+label+'. '+description+'. '+details)
text_tile('12-16pc-copy','16 <span class="unit">PC FOOD</span>','Storage for a well-prepared week.','Fresh lunches. Colorful sides. Everything in its place.','8 glass containers + 8 lids · 30 oz each','YOUR WEEK, WELL PREPARED','16-piece glass set')
text_tile('13-6500-copy','6500 <span class="unit">ML</span>','Extra-large glass food storage.','Make room for family portions, generous salads, and good food worth sharing.','6500 ml / 220 oz · Locking lid with carry handle','A LITTLE MORE ROOM','6500 ml large container')
add('14-6500-photo','Large photo tile',f'<img class="scene" src="{photo("6500-ml-large-food-storage-container-1.webp")}" alt=""><p class="caption" data-safe>Freshness, on a generous scale.</p>','square photo-tile',False,1500,1500,product='6500 ml large container',alt='RAZAB 6500 ml glass container with a roast and vegetables, clear locking lid and handle.',source='Original RAZAB manufacturer photograph')
banner('15-storage-sets',photo('16-pc-glass-set-4.webp'),'16 <span class="unit">PC</span>','Fresh meals. A calmer fridge.','A coordinated collection for colorful lunches, ready-to-go sides, and a well-prepared week.',['8 glass containers + 8 lids','30 oz each'],'PREP TODAY. ENJOY TOMORROW.','collection','16-piece glass set','Original RAZAB website product photograph')
banner('16-1860-prep',photo('1860-ml-glass-0.webp'),'1860 <span class="unit">ML / 63 OZ</span><br><span class="title">MEAL PREP</span>','Fresh possibilities, stacked.','Keep today’s lunch and tomorrow’s plans beautifully together. A pair made for your everyday rhythm.',['2 containers + 2 lids','1860 ml / 63 oz each'],'KEEP IT FRESH, KEEP IT RAZAB','final','1860 ml glass set of 2','Original RAZAB manufacturer photograph')
categories=[('17-category-prep','16-pc-glass-set-9.webp','01 / SHOP BY USE','Meal prep','Set your week in order.','16-piece glass set','meal-prep'),('18-category-storage','6500-ml-large-food-storage-container-15.webp','02 / SHOP BY USE','Family storage','Room for the generous meal.','6500 ml large container','food-storage'),('19-category-bake','set-of-2-glass-loaf-pans-0.webp','03 / SHOP BY USE','Glass bakeware','For recipes worth sharing.','Set of 2 glass loaf pans','loaf-pans')]
for id,name,prefix,title,description,product,target in categories:
 body=f'<img class="scene" src="{photo(name)}" alt=""><div class="category-copy"><span class="eyebrow" data-safe>{prefix}</span><h2 data-safe>{title}</h2><p data-safe>{description}</p><span class="category-link" data-safe>Explore the collection <b aria-hidden="true">↗</b></span></div>'
 add(id,'Category image tile',body,'category',False,1000,1300,product=product,copy=dict(heading=title,body=description,linkText='Explore the collection',previewTarget=target),alt=title+'. '+description,source='Original RAZAB website product photograph')
sizes=[dict(capacity='1860',unit='ml each',label='The everyday pair',detail='2 containers + 2 lids · 63 oz each',file='1860-ml-glass-11.webp',url=product_urls['1860 ml glass set of 2']),dict(capacity='4800',unit='ml',label='For bigger batches',detail='1 container + 1 lid · 163 oz',file='4800-ml-glass-container-with-locking-lid-0.webp',url=product_urls['4800 ml large container']),dict(capacity='6500',unit='ml',label='The whole table',detail='1 container + 1 lid · 220 oz',file='6500-ml-large-food-storage-container-7.webp',url=product_urls['6500 ml large container'])]
guide='<p class="eyebrow" data-safe>THE RAZAB SIZE GUIDE</p><h2 class="section-title" data-safe>Find your everyday size.</h2><p class="section-intro" data-safe>Compare capacity and set contents at a glance.</p><div class="guide-grid">'
for s in sizes:guide+=f'<article class="size-card"><img class="size-photo" src="{photo(s["file"])}" alt=""><div class="size-copy"><h3 data-safe>{s["capacity"]} <span>{s["unit"]}</span></h3><p class="size-label" data-safe>{s["label"]}</p><p class="size-detail" data-safe>{s["detail"]}</p></div></article>'
guide+='</div>'
add('20-size-guide','Full-width capacity guide',guide,'size-guide',height=1600,copy=dict(heading='Find your everyday size.',body='Compare capacity and set contents at a glance.',sizes=sizes),alt='RAZAB size guide. 1860 ml each: two containers and two lids, 63 oz each. 4800 ml: one container and one lid, 163 oz. 6500 ml: one container and one lid, 220 oz.',source='Original RAZAB website product photographs')
banner('21-batch-storage',photo('4800-ml-glass-container-with-locking-lid-0.webp'),'4800 <span class="unit">ML</span>','A little more room for good food.','The pasta bake. The big batch of soup. The generous portions you save for another day.',['1 glass container + 1 lid','163 oz capacity'],'MADE FOR BIGGER BATCHES','batch','4800 ml large container','Original RAZAB website product photograph')
care_rules=[('01 / Heat the glass.','Remove plastic lids before oven or microwave use.'),('02 / Clean with care.','Use the top dishwasher rack or wash by hand.'),('03 / Let temperatures settle.','Avoid sudden changes from freezer to oven.')]
care=f'<img class="scene" src="{photo("set-of-2-glass-loaf-pans-3.webp")}" alt=""><div class="copy"><p class="eyebrow" data-safe>RAZAB / USE & CARE</p><h2 class="care-title" data-safe>Good glass.<br>A little care.</h2><p class="description" data-safe>Simple habits for the pieces you reach for every day.</p><div class="care-rules">'
for title,description in care_rules:care+=f'<article class="care-rule"><h3 data-safe>{title}</h3><p data-safe>{description}</p></article>'
care+='</div></div>'
add('22-glass-care','Full-width use and care image',care,'care-art',product='Set of 2 glass loaf pans',copy=dict(heading='Good glass. A little care.',rules=care_rules),alt='RAZAB glass care. Remove lids before oven or microwave use. Top-rack dishwasher cleaning or hand washing. Avoid sudden temperature changes.',source='Original RAZAB website product photograph')
closing='<img class="closing-logo" data-safe src="../razab-original-logo.png" alt="RAZAB"><h2 data-safe>Keep It Fresh, Keep It Razab.</h2><p data-safe>Glass storage. Thoughtfully made for everyday living.</p>'
add('23-brand-close','Full-width brand closing',closing,'closing',height=500,copy=dict(heading='Keep It Fresh, Keep It Razab.',body='Glass storage. Thoughtfully made for everyday living.'),alt='RAZAB. Keep It Fresh, Keep It Razab. Glass storage. Thoughtfully made for everyday living.',source='Original RAZAB logo')
module_order=['01-header','02-welcome','17-category-prep','18-category-storage','19-category-bake','03-meal-prep','04-glass','05-lids','06-lock','07-care','20-size-guide','08-extra-large','21-batch-storage','09-loaf-pan','10-everyday','11-16pc-photo','12-16pc-copy','13-6500-copy','14-6500-photo','15-storage-sets','16-1860-prep','22-glass-care','23-brand-close']
modules.sort(key=lambda m:module_order.index(m['id']))
art.append('<section class="artboard logo-art" id="store-logo" data-export="store-logo.png"><img src="../razab-original-logo.png" alt="Original RAZAB logo"></section>')
(assets/'module-artwork.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>RAZAB — Benchmark Module Artwork</title><style>'+css+'</style></head><body>'+''.join(art)+'</body></html>',encoding='utf-8')
order=['Kitchen header','Amazon navigation','Thank-you band','Shop by use: three category tiles','16 PC meal prep','Four terracotta features','Capacity guide','6500 ml extra large','4800 ml batch storage','Loaf pan','1860 ml everyday','16 PC / 6500 ml checkerboard','16 PC storage collection','1860 ml / 63 oz meal prep','Glass use and care','Brand closing']
manifest=dict(brand='RAZAB',format='Amazon Brand Store image modules',benchmark='../../../razab-full-page.jpg',sectionOrder=order,headerSafeZone=dict(left=450,right=2550),contentSectionCount=15,photographyPolicy='Only original images downloaded from RAZAB website product galleries. Cached originals are unchanged; source URLs and SHA-256 hashes are recorded per module.',visualPolicy='Copy sits on opaque brand backgrounds beside or below unshaded photographs. No gradient overlays or text shadows are applied.',notes=['Local HTML previews image modules. Upload separate images through Amazon Store Builder.','Navigation belongs to the Amazon Store interface.','The original benchmark product sections retain their relative order, with five additional sections for category discovery, sizing, batch storage, care and brand closing.','All product photos are original RAZAB website assets.','Amazon destinations are unassigned; confirm current ASINs in Store Builder.','Category links scroll to matching sections in the local preview; assign Store-page destinations in Builder.'],modules=modules)
(assets/'upload-manifest.json').write_text(json.dumps(manifest,indent=2,ensure_ascii=False),encoding='utf-8')
def picture(m):
 mobile='<source media="(max-width:700px)" srcset="assets/amazon-store/'+m['mobile']+'">' if m['mobile'] else ''
 return f'<picture>{mobile}<img src="assets/amazon-store/{m["desktop"]}" alt="{esc(m["alt"])}" width="{m["width"]}" height="{m["height"]}" loading="{"eager" if m["id"]=="01-header" else "lazy"}" decoding="async"></picture>'
byid={m['id']:m for m in modules}
previewcss='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:18px}body{margin:0;background:#fff;color:#2c2a25;font:14px/1.5 Arial,sans-serif}img{display:block;max-width:100%;height:auto}a{color:inherit;text-decoration:none}:focus-visible{outline:3px solid #c56950;outline-offset:4px}.store{max-width:1280px;margin:20px auto 48px;padding:0 16px}.store-header{margin:0}.store-header picture{overflow:hidden}.store-nav{display:flex;align-items:center;gap:30px;border-block:1px solid #ddd;padding:10px 18px;margin:0 0 18px;overflow-x:auto;white-space:nowrap}.store-nav .brand{width:108px;margin-right:6px;flex-shrink:0}.store-nav a{font-size:12px;min-height:40px;display:flex;align-items:center;flex-shrink:0}.store-nav .selected{font-weight:bold;border-bottom:2px solid #c56950}.store-nav .follow{margin-left:auto;color:#6b6960;font-size:11px;letter-spacing:.08em}.module{margin:0 0 18px;scroll-margin-top:18px}.feature-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.split-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-bottom:18px}.feature-row figure,.split-row figure{margin:0;min-width:0}picture{display:block}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}.preview-note{text-align:center;color:#6b6960;font-size:11px;padding:0 20px 24px;margin:0 auto;max-width:850px}@media(max-width:700px){.store{margin:8px auto 24px;padding:0 8px}.store-header img{width:142.857%;max-width:none;transform:translateX(-15%)}.store-nav{gap:23px;padding:7px 12px;margin-bottom:8px}.store-nav .brand{width:85px}.store-nav a{font-size:11px}.store-nav .follow{display:none}.module{margin-bottom:8px}.feature-row{grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px}.split-row{grid-template-columns:1fr;gap:8px;margin-bottom:8px}.tile16photo{order:1}.tile16copy{order:2}.tile6500photo{order:3}.tile6500copy{order:4}.preview-note{font-size:10px;line-height:1.7}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
previewcss+='\n.category-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:24px}.category-row figure{margin:0;min-width:0}.category-row a{display:block}.module{margin-bottom:24px}.feature-row,.split-row{gap:18px;margin-bottom:24px}@media(max-width:700px){.category-row{grid-template-columns:1fr;gap:10px;margin-bottom:10px}.module{margin-bottom:10px}.feature-row,.split-row{gap:10px;margin-bottom:10px}}'
body='<a class="sr-only" href="#meal-prep">Skip to the collection</a><main class="store" id="home"><h1 class="sr-only">RAZAB Amazon Storefront — The Complete Collection</h1><header class="store-header">'+picture(byid['01-header'])+'</header><nav class="store-nav" aria-label="Amazon Store navigation preview"><a href="#home" class="brand" aria-label="RAZAB home"><img src="assets/razab-original-logo.png" alt="RAZAB" width="1902" height="492"></a><a class="selected" href="#home">Home</a><a href="#meal-prep">Meal Prep</a><a href="#food-storage">Food Storage</a><a href="#loaf-pans">Loaf Pans</a><a href="#sizes">Size Guide</a><a href="#glass-care">Care</a><span class="follow">RAZAB BRAND STORE</span></nav>'
ids={'02-welcome':'welcome','03-meal-prep':'meal-prep','08-extra-large':'food-storage','09-loaf-pan':'loaf-pans','10-everyday':'everyday','15-storage-sets':'storage-sets','16-1860-prep':'meal-prep-pair','20-size-guide':'sizes','21-batch-storage':'batch-storage','22-glass-care':'glass-care','23-brand-close':'brand-close'}
for id in ['02-welcome','categories','03-meal-prep','features','20-size-guide','08-extra-large','21-batch-storage','09-loaf-pan','10-everyday','split','15-storage-sets','16-1860-prep','22-glass-care','23-brand-close']:
 if id=='features':body+='<section class="feature-row" aria-label="Four glass storage features">'+''.join('<figure>'+picture(byid[k])+'</figure>' for k in ['04-glass','05-lids','06-lock','07-care'])+'</section>'
